INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO320-013','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest DDR5 memory training','What DDR5 memory training is','description: Platforma może wykonywać inicjalizację i trening pamięci po zmianie modułów lub ustawień. Czas i zachowanie zależą od BIOS i konfiguracji. step: Po zmianie RAM stosuj instrukcję płyty i ustawienia bazowe.','descriptionEn: A platform may perform memory initialization and training after module or settings changes. Timing and behaviour depend on BIOS and configuration. stepEn: After changing memory, follow the motherboard manual and allow the documented training process to finish.','',''),
('beginner:ZERO320-014','beginner','Podstawy i pojęcia / Fundamentals and concepts','JEDEC, XMP i EXPO','JEDEC, XMP and EXPO','description: JEDEC opisuje standardowe profile pracy pamięci; XMP i EXPO są profilami rozszerzonymi zależnymi od obsługi platformy. step: Najpierw testuj stabilność przy ustawieniach bazowych.','descriptionEn: JEDEC describes standard memory profiles; XMP and EXPO are extended profiles dependent on platform support. stepEn: Establish stability with JEDEC defaults before enabling XMP or EXPO.','',''),
('beginner:ZERO320-015','beginner','Podstawy i pojęcia / Fundamentals and concepts','Co oznacza QVL','What QVL means','description: QVL to lista modułów przetestowanych przez producenta w określonej konfiguracji. Brak modułu na liście nie zawsze oznacza niezgodność, ale lista jest punktem odniesienia. step: Porównaj model modułu, pojemność, liczbę kości i wersję BIOS.','descriptionEn: QVL is a list of modules tested by the manufacturer in a specified configuration. Absence from the list does not always mean incompatibility, but it is a reference. stepEn: Compare the exact module part number, capacity, module count and BIOS version with the QVL.','',''),
('beginner:ZERO320-016','beginner','Podstawy i pojęcia / Fundamentals and concepts','WHEA i błędy sprzętowe Windows','WHEA and Windows hardware errors','description: WHEA raportuje błędy sprzętowe/platformowe. Trzeba czytać pełny wpis i kontekst, a nie tylko nazwę źródła zdarzenia. step: Zapisz ID zdarzenia, parametry i czas oraz porównaj z obciążeniem.','descriptionEn: WHEA reports hardware/platform errors. Read the full event and context rather than only the event source name. stepEn: Record the WHEA event ID, parameters and timestamp, then compare them with the workload.','',''),
('beginner:ZERO320-017','beginner','Podstawy i pojęcia / Fundamentals and concepts','Co to jest minidump','What a minidump is','description: Minidump to zrzut informacji diagnostycznych po awarii Windows. Może zawierać wrażliwe dane i powinien być traktowany prywatnie. step: Analizuj lokalnie i udostępniaj tylko zanonimizowane fragmenty.','descriptionEn: A minidump contains diagnostic information after a Windows crash. It may include sensitive data and should be handled privately. stepEn: Analyze dump files locally and share only sanitized excerpts that do not expose customer data.','',''),
('beginner:ZERO320-018','beginner','Podstawy i pojęcia / Fundamentals and concepts','WinRE i narzędzia odzyskiwania','WinRE and recovery tools','description: WinRE to środowisko odzyskiwania Windows zawierające narzędzia naprawy rozruchu i przywracania. Niektóre działania wymagają klucza BitLocker. step: Przed naprawą potwierdź stan szyfrowania i zabezpiecz dane.','descriptionEn: WinRE is the Windows Recovery Environment with startup repair and recovery tools. Some actions require a BitLocker recovery key. stepEn: Before recovery work, confirm encryption status, locate the recovery key with the owner and protect the data.','',''),
('beginner:ZERO320-019','beginner','Podstawy i pojęcia / Fundamentals and concepts','Różnica SFC i DISM','SFC versus DISM','description: SFC weryfikuje pliki systemowe, a DISM obsługuje obraz Windows. Dobór kolejności zależy od sytuacji i dokumentacji Microsoft. step: Zapisz wynik każdej komendy i logi diagnostyczne.','descriptionEn: SFC verifies system files, while DISM services the Windows image. The right sequence depends on the scenario and Microsoft guidance. stepEn: Record the result of each SFC or DISM command and preserve the relevant diagnostic logs.','',''),
('beginner:ZERO320-020','beginner','Podstawy i pojęcia / Fundamentals and concepts','Autotest diagnostyczny OEM','OEM pre-boot diagnostics','description: Producenci udostępniają testy sprzętu z poziomu UEFI lub narzędzi Windows. Wynik i kod usterki należy zachować w raporcie. step: Użyj narzędzia właściwego dla marki i modelu.','descriptionEn: Manufacturers provide hardware tests from UEFI or Windows tools. Preserve results and failure codes in the service report. stepEn: Use the diagnostic utility intended for the exact manufacturer and device model.','',''),
('beginner:ZERO320-021','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest POST','What POST is','description: POST to etap wstępnej kontroli sprzętu przed uruchomieniem systemu. Kody LED, beep i Q-Code są zależne od producenta. step: Odczytuj kody z instrukcji konkretnej płyty.','descriptionEn: POST is the initial hardware check before OS startup. LED, beep and Q-Code meanings vary by manufacturer. stepEn: Interpret POST codes using the manual for the exact motherboard or system model.','',''),
('beginner:ZERO320-022','beginner','Podstawy i pojęcia / Fundamentals and concepts','Sekwencja zasilania laptopa','Laptop power sequence','description: Płyta uruchamia napięcia i sygnały sterujące w określonej kolejności. Nazwy i zakresy zależą od platformy. step: Nie przenoś wartości pomiarowych z innej rewizji.','descriptionEn: The board brings up rails and control signals in a defined sequence. Names and values depend on the platform. stepEn: Do not reuse measurement values from another board revision; consult the matching schematic and service guide.','',''),
('beginner:ZERO320-023','beginner','Podstawy i pojęcia / Fundamentals and concepts','Rola MOSFET w torze zasilania','MOSFET role in a power path','description: MOSFET może przełączać lub chronić tor zasilania. Ocena wymaga schematu i pomiarów w odpowiednim stanie układu. step: Nie mostkuj tranzystora ani zabezpieczenia.','descriptionEn: A MOSFET may switch or protect a power path. Evaluation requires the schematic and measurements in the correct circuit state. stepEn: Never bridge a MOSFET or protection device; identify the circuit and cause of the fault first.','',''),
('beginner:ZERO320-024','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest BoardView','What BoardView is','description: BoardView pokazuje rozmieszczenie elementów i połączenia na PCB. Musi odpowiadać konkretnej rewizji płyty. step: Sprawdź numer płyty i zgodność pliku przed użyciem.','descriptionEn: BoardView shows component placement and PCB connections. It must match the exact board revision. stepEn: Verify the board number and file revision before using a BoardView layout.','',''),
('beginner:ZERO320-025','beginner','Podstawy i pojęcia / Fundamentals and concepts','Dlaczego obraz zewnętrzny pomaga','Why an external display helps','description: Test z monitorem zewnętrznym pomaga oddzielić tor obrazu GPU od panelu, taśmy, podświetlenia i czujnika pokrywy. step: Porównuj na znanym sprawnym kablu i wejściu.','descriptionEn: An external display helps separate GPU output from panel, cable, backlight and lid-sensor faults. stepEn: Compare the result using a known-good cable, display and input port.','',''),
('beginner:ZERO320-026','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest throttling','What thermal/power throttling means','description: Throttling ogranicza wydajność przy limitach temperatury, mocy lub prądu. Odczyty wymagają interpretacji względem specyfikacji CPU/GPU. step: Zapisz temperaturę, moc, zegary i flagi limitów.','descriptionEn: Throttling limits performance at thermal, power or current limits. Readings must be interpreted against CPU/GPU specifications. stepEn: Record temperature, power, clock frequency and the active performance-limit flags.','',''),
('beginner:ZERO320-027','beginner','Podstawy i pojęcia / Fundamentals and concepts','Różnica temperatury CPU i hotspot GPU','CPU temperature versus GPU hotspot','description: Różne czujniki raportują różne punkty układu. Nie porównuj liczb bez nazwy czujnika i dokumentacji. step: Zapisz konkretny sensor, jednostkę i stan obciążenia.','descriptionEn: Different sensors report different parts of a chip. Do not compare values without sensor names and documentation. stepEn: Record the exact sensor name, unit and workload state when comparing CPU temperature and GPU hotspot.','',''),
('beginner:ZERO320-028','beginner','Podstawy i pojęcia / Fundamentals and concepts','Dlaczego nie otwierać zasilacza','Why not to open a PSU','description: Zasilacz sieciowy może zawierać kondensatory utrzymujące niebezpieczne napięcie także po odłączeniu z sieci. step: Wymieniaj kompletny zasilacz; nie otwieraj jego obudowy.','descriptionEn: A mains power supply may contain capacitors that retain hazardous voltage after disconnection. stepEn: Replace a faulty mains PSU as a complete unit; never open its enclosure.','',''),
('beginner:ZERO320-029','beginner','Podstawy i pojęcia / Fundamentals and concepts','ESD: wyrównanie potencjałów','ESD: equipotential bonding','description: Ochrona ESD ogranicza ryzyko uszkodzeń wyładowaniem elektrostatycznym. Nie zastępuje ochrony przed porażeniem. step: Używaj maty i opaski zgodnie z procedurą stanowiska.','descriptionEn: ESD controls reduce electrostatic damage risk. They do not replace protection against electric shock. stepEn: Use the ESD mat and wrist strap according to the documented workstation procedure.','',''),
('beginner:ZERO320-030','beginner','Podstawy i pojęcia / Fundamentals and concepts','Bezpieczne obchodzenie się z baterią litową','Safe handling of lithium batteries','description: Spuchnięcie, zapach, wysoka temperatura lub uszkodzenie mechaniczne baterii oznacza ryzyko i konieczność przerwania pracy. step: Nie przebijaj, nie ściskaj i nie ładuj uszkodzonej baterii.','descriptionEn: Swelling, odour, high temperature or mechanical damage to a battery indicates risk and requires stopping work. stepEn: Do not puncture, crush or charge a damaged lithium battery; isolate the device and follow the safety procedure.','',''),
('beginner:ZERO320-031','beginner','Podstawy i pojęcia / Fundamentals and concepts','Rola firmware routera','Router firmware role','description: Firmware routera obsługuje routing, Wi-Fi, DHCP, NAT i zabezpieczenia. Aktualizacja musi być zgodna z modelem i rewizją. step: Zapisz konfigurację i używaj wyłącznie pliku producenta.','descriptionEn: Router firmware provides routing, Wi-Fi, DHCP, NAT and security functions. Updates must match model and revision. stepEn: Record router configuration and obtain firmware only from the exact device manufacturer support page.','',''),
('beginner:ZERO320-032','beginner','Podstawy i pojęcia / Fundamentals and concepts','WPA2 i WPA3','WPA2 and WPA3','description: WPA2 i WPA3 to mechanizmy bezpieczeństwa sieci Wi-Fi. Dobór trybu zależy od obsługi routera i klientów. step: Nie osłabiaj szyfrowania w sieci klienta bez zgody.','descriptionEn: WPA2 and WPA3 are Wi-Fi security mechanisms. Mode selection depends on router and client support. stepEn: Do not weaken network encryption or change customer security settings without explicit authorization.','',''),
('beginner:ZERO320-033','beginner','Podstawy i pojęcia / Fundamentals and concepts','Rola DHCP i DNS','Role of DHCP and DNS','description: DHCP przydziela konfigurację IP, a DNS tłumaczy nazwy hostów na adresy. Błędy tych usług mogą wyglądać jak brak Internetu. step: Testuj adres IP, bramę, DNS i dostęp z urządzenia referencyjnego.','descriptionEn: DHCP assigns IP configuration, while DNS resolves hostnames. Failures can look like an internet outage. stepEn: Test the client IP address, gateway, DNS resolution and connectivity using a known-good reference device.','',''),
('beginner:ZERO320-034','beginner','Podstawy i pojęcia / Fundamentals and concepts','Dlaczego raport serwisowy jest ważny','Why the service report matters','description: Raport dokumentuje objaw, test, wynik, wykonaną zmianę, część i ograniczenia. Ułatwia odtworzenie pracy i odpowiedzialność serwisu. step: Nie wpisuj haseł, kluczy odzyskiwania ani niepotrzebnych danych klienta.','descriptionEn: A report documents symptom, test, result, repair, part and limitations. It supports reproducibility and service accountability. stepEn: Do not include passwords, recovery keys or unnecessary personal information in service reports.','',''),
('topic:KURS-001','topic','','Płyta główna','','description: Centralny element łączący wszystkie podzespoły. Awarie objawiają się brakiem startu, restartami lub błędami POST. symptoms: • Komputer nie startuje / brak sygnału wideo • Piski POST przy uruchomieniu • Losowe restarty i zawieszenia • Nie wykrywa RAM, dysków lub portów USB • Spuchnięte / wyciekające kondensatory diagnosis: • Sprawdź diody debug LED / kod POST na płycie. • Odłącz wszystko poza CPU + 1 kość RAM i spróbuj uruchomić. • Obejrzyj kondensatory pod kątem wybrzuszeń i przebarwień. • Zresetuj BIOS (wyjmij baterię CMOS na 30 s). repair: • Wyczyść gniazdo i styki, zresetuj CMOS. • Zaktualizuj / odtwórz BIOS z pendrive (BIOS Flashback). • Wymień baterię CMOS (CR2032). • Przelutuj lub wymień spuchnięte kondensatory (serwis). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-002','topic','','Procesor (CPU)','','description: Serce komputera. Problemy to najczęściej przegrzewanie, throttling i niestabilność. symptoms: • Wysokie temperatury (>90°C) i throttling • Nagłe wyłączenia pod obciążeniem • Niska wydajność w testach • Niebieskie ekrany (BSOD) WHEA diagnosis: • Zmierz temperatury (HWiNFO) w spoczynku i pod obciążeniem. • Uruchom test stabilności 5–30 min i obserwuj throttling. • Sprawdź czy pasta termiczna nie wyschła. repair: • Wymień pastę termoprzewodzącą. • Popraw montaż chłodzenia (docisk, wentylatory). • Wyłącz niestabilny overclock / ustaw XMP prawidłowo. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-003','topic','','Karta graficzna (GPU)','','description: Odpowiada za grafikę i gry. Objawy awarii: artefakty, brak obrazu, przegrzewanie. symptoms: • Artefakty graficzne / kolorowe piksele • Czarny ekran w grach • Głośne wentylatory, wysoka temperatura • Sterownik przestał odpowiadać diagnosis: • Uruchom benchmark GPU i obserwuj artefakty/temperatury. • Sprawdź podłączenie zasilania PCIe. • Przetestuj kartę w innym komputerze / slocie. repair: • Zaktualizuj/przeinstaluj sterowniki (czysta instalacja DDU). • Wyczyść wentylatory i radiator ze sprężonym powietrzem. • Wymień pastę i pady termiczne na GPU. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-004','topic','','Pamięć RAM','','description: Pamięć operacyjna. Uszkodzenia powodują błędy, BSOD i losowe zawieszenia. symptoms: • Częste niebieskie ekrany (BSOD) • Losowe zawieszenia i restarty • Błędy przy uruchamianiu aplikacji • Komputer nie wykrywa pełnej ilości RAM diagnosis: • Uruchom MemTest86 przez min. 2 przebiegi. • Testuj kości pojedynczo w różnych slotach. • Sprawdź profil XMP/EXPO w BIOS. repair: • Wyczyść styki kości (gumka + IPA). • Przełóż kości do prawidłowych slotów (dual channel). • Wymień uszkodzoną kość. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-005','topic','','Dysk (SSD / HDD)','','description: Przechowuje dane. Awarie: spadek prędkości, klikanie HDD, znikające pliki. symptoms: • System bardzo wolno się uruchamia • Klikanie / stukanie (HDD) • Błędy odczytu, znikające pliki • Dysk niewidoczny w BIOS diagnosis: • Sprawdź stan S.M.A.R.T. (CrystalDiskInfo). • Uruchom test prędkości sekwencyjnej i losowej. • Sprawdź kable SATA / gniazdo M.2. repair: • Wykonaj kopię zapasową NATYCHMIAST przy błędach. • Zaktualizuj firmware SSD. • Wymień kabel SATA lub przenieś na inny port. • Wymień dysk gdy S.M.A.R.T. zgłasza błędy. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-006','topic','','Zasilacz (PSU)','','description: Zasila cały komputer. Wadliwy PSU powoduje restarty, brak startu i uszkodzenia. symptoms: • Komputer nie włącza się wcale • Restarty pod obciążeniem (gry) • Zapach spalenizny, trzaski • Wentylator PSU nie kręci się diagnosis: • Test zworką (paper-clip test) — wentylator rusza. • Zmierz napięcia miernikiem (12V/5V/3.3V). • Sprawdź obciążenie vs moc znamionową. repair: • Wymień wadliwy zasilacz (nie naprawiać samodzielnie!). • Dobierz moc z zapasem 20–30%. • Użyj markowego PSU z certyfikatem 80 PLUS. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-007','topic','','Chłodzenie','','description: Wentylatory, radiatory i AIO. Złe chłodzenie = throttling i głośna praca. symptoms: • Bardzo wysokie temperatury CPU/GPU • Głośne, ciągle kręcące się wentylatory • Throttling i spadki wydajności • Kurz w radiatorach diagnosis: • Zmierz temperatury pod obciążeniem. • Sprawdź krzywe wentylatorów w BIOS. • Obejrzyj radiatory pod kątem kurzu. repair: • Wyczyść radiatory i wentylatory sprężonym powietrzem. • Wymień pastę termiczną. • Popraw airflow (ustawienie wentylatorów in/out). • Wymień uszkodzony wentylator / pompkę AIO. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-008','topic','','Cache / BIOS','','description: Pamięć podręczna CPU i ustawienia BIOS wpływają na stabilność i wydajność. symptoms: • Błędy WHEA / niestabilność przy OC • Zły profil pamięci (brak XMP) • Nieaktualny mikrokod BIOS diagnosis: • Sprawdź wersję BIOS vs najnowsza na stronie producenta. • Zweryfikuj rozmiary cache L1/L2/L3 (CPU-Z). • Uruchom test stabilności cache (np. Prime95). repair: • Zaktualizuj BIOS do najnowszej wersji. • Włącz XMP/EXPO dla RAM. • Przywróć ustawienia domyślne przy niestabilności. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-009','topic','','Ekran / matryca laptopa','','description: Matryca, taśma LVDS/eDP i podświetlenie. Objawy: brak obrazu, plamy, migotanie. symptoms: • Czarny ekran, ale laptop działa (podświetlenie) • Pęknięta matryca / plamy atramentowe • Migotanie lub paski na ekranie • Martwe piksele diagnosis: • Podłącz zewnętrzny monitor — jeśli działa, wina matrycy/taśmy. • Sprawdź podświetlenie latarką pod kątem. • Porusz pokrywą — migotanie sugeruje taśmę. repair: • Wymień taśmę LVDS/eDP. • Wymień matrycę (dopasuj rozdzielczość i złącze). • Wymień inwerter/podświetlenie (starsze modele). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-010','topic','','Sieć / WiFi','','description: Karta sieciowa, WiFi i sterowniki. Objawy: brak internetu, zrywanie połączenia. symptoms: • Brak WiFi / karta niewidoczna • Częste rozłączenia • Niska prędkość transferu • Wykrzyknik w Menedżerze urządzeń diagnosis: • Sprawdź kartę w Menedżerze urządzeń. • Przetestuj innym kablem / routerem. • Zresetuj stos sieciowy (netsh winsock reset). repair: • Zaktualizuj/przeinstaluj sterowniki sieciowe. • Wymień moduł WiFi M.2 (karta 2230). • Dodaj kartę WiFi USB jako alternatywę. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-011','topic','','Dźwięk / audio','','description: Układ audio, głośniki i gniazdo słuchawek. Objawy: brak dźwięku, trzaski. symptoms: • Brak dźwięku z głośników • Trzaski / szumy • Gniazdo słuchawek nie działa • Mikrofon nie nagrywa diagnosis: • Sprawdź urządzenie domyślne w ustawieniach dźwięku. • Przetestuj słuchawkami — izoluje głośniki. • Uruchom narzędzie do rozwiązywania problemów audio. repair: • Zaktualizuj sterowniki audio (Realtek). • Wymień uszkodzone głośniki / gniazdo jack. • Sprawdź taśmę głośników w laptopie. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-012','topic','','Bateria laptopa','','description: Ogniwa baterii zużywają się z czasem. Objawy: krótki czas pracy, puchnięcie. symptoms: • Bardzo krótki czas pracy na baterii • Bateria spuchnięta (touchpad się wybrzusza) • Laptop działa tylko na zasilaczu • Nagłe wyłączenia diagnosis: • Sprawdź raport baterii (powercfg /batteryreport). • Porównaj pojemność projektową vs aktualną. • Obejrzyj obudowę pod kątem puchnięcia. repair: • Wymień baterię na oryginalną / dobrej jakości. • NIE używaj spuchniętej baterii — ryzyko pożaru. • Skalibruj nową baterię (pełny cykl). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-013','topic','','Przegrzewanie laptopa','','description: Kurz w układzie chłodzenia, wyschnięta pasta i zapchane wyloty powietrza powodują throttling, głośną pracę i nagłe wyłączenia laptopa. symptoms: • Głośne wentylatory i gorąca obudowa • Spadki FPS / throttling po kilku minutach • Nagłe wyłączenia pod obciążeniem • Wentylator ciągle na maksymalnych obrotach • Gorące powietrze słabo wydostaje się z wylotów diagnosis: • Zmierz temperatury CPU/GPU w spoczynku i pod obciążeniem (HWiNFO). • Sprawdź wyloty powietrza pod kątem kurzu i zablokowania. • Nasłuchaj wentylatora — grzechotanie sugeruje zużyte łożysko. • Porównaj pracę na twardym podłożu vs miękkim (koc zatyka wloty). repair: • Przedmuchaj wyloty i radiator sprężonym powietrzem. • Wymień pastę termiczną i pady termiczne (miedziane/grafenowe). • Wyczyść lub wymień zużyty wentylator. • Zastosuj undervolting CPU (ThrottleStop / BIOS). • Używaj podkładki chłodzącej i nie zasłaniaj wlotów. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron');
